// ─────────────────────────── 유틸 ───────────────────────────
function hash32(str) {
  let h = 2166136261 >>> 0;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619) >>> 0;
  }
  return h;
}
function seedInt(seed, salt, max) {
  return hash32(seed + ':' + salt) % max;
}
function pickOne(arr, seed, salt = '') {
  return arr[seedInt(seed, salt, arr.length)];
}
function pickN(arr, seed, n, salt = '') {
  const used = new Set();
  const out = [];
  let i = 0;
  while (out.length < n && i < arr.length * 3) {
    const idx = seedInt(seed, salt + ':' + i, arr.length);
    if (!used.has(idx)) { used.add(idx); out.push(arr[idx]); }
    i++;
  }
  return out;
}
function fill(template, vars) {
  return template.replace(/\{(\w+)\}/g, (_, k) => vars[k] != null ? vars[k] : '');
}
function escapeHtml(str) {
  if (str == null) return '';
  return String(str).replace(/[&<>"']/g, ch => ({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'
  }[ch]));
}
function escapeXml(str) {
  return String(str).replace(/[&<>"']/g, ch => ({
    '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'
  }[ch]));
}
function encodeKor(s) {
  return encodeURIComponent(s);
}
function urlPath(...parts) {
  return '/' + parts.filter(Boolean).map(encodeKor).join('/');
}

