// 지역 썸네일: 지역 시드로 실제 사진 (picsum.photos, 안정적·재현 가능)
// 같은 지역은 항상 같은 사진. picsum은 무료 placeholder 서비스.
function regionThumbnail(loc, seed, w = 1200, h = 480) {
  const safeSeed = encodeURIComponent(seed.replace(/[^\w가-힣]/g, ''));
  return `<img src="https://picsum.photos/seed/${safeSeed}/${w}/${h}" 
    alt="${escapeHtml(loc)} 지역 사진" 
    loading="lazy" decoding="async"
    width="${w}" height="${h}"
    style="width:100%;height:100%;object-fit:cover;display:block">`;
}

// 제품용 부드러운 그라데이션 배경 (제품 페이지 비주얼)
function productPhotoBg(productSlug, seed) {
  const safeSeed = encodeURIComponent('product-' + productSlug + '-' + seed);
  return `<img src="https://picsum.photos/seed/${safeSeed}/1200/600" 
    alt="${escapeHtml(productSlug)}" 
    loading="lazy" decoding="async"
    style="width:100%;height:100%;object-fit:cover;opacity:0.15;position:absolute;inset:0">`;
}

