// ─────────────────────── 동×제품 페이지 ───────────────────────
function dongProductPage(short, sigungu, dong, productSlug) {
  const r = getRegion(short);
  if (!r || !r.d[sigungu] || !r.d[sigungu].includes(dong)) return null;
  const product = findProduct(productSlug);
  if (!product) return null;
  const meta = REGION_META[short] || {};
  const seed = `dp:${short}:${sigungu}:${dong}:${productSlug}`;
  const loc = dong;
  const fullLoc = `${r.f} ${sigungu} ${dong}`;
  const heroHeadline = fill(pickOne(HEADLINES_PRODUCT, seed, 'h'), { loc, product: product.name });
  const heroSub = fill(pickOne(SUBCOPY_PRODUCT, seed, 'sub'), { loc, product: product.name });
  const fitText = fill(pickOne(PRODUCT_FIT[product.slug], seed, 'fit'), {
    loc: fullLoc, focus: meta.focus || '', tip: meta.tip || ''
  });
  const fitText2 = fill(pickOne(PRODUCT_FIT[product.slug], seed, 'fit2'), {
    loc: fullLoc, focus: meta.focus || '', tip: meta.tip || ''
  });
  const intro2 = fill(pickOne(REGION_INTRO, seed, 'intro'), {
    loc: fullLoc, focus: meta.focus || '다양한 상권', tip: meta.tip || '',
    population: meta.population || '', storeListShort: (meta.stores || []).slice(0,3).join('·')
  });
  const insight = fill(pickOne(LOCAL_INSIGHTS, seed, 'ins'), { loc, focus: meta.focus || '', tip: meta.tip || '' });
  const faqs = product.faq.slice(0, 3).concat(
    pickN(FAQ_REGIONAL, seed, 2, 'faq').map(f => ({
      q: fill(f.q, { loc }),
      a: fill(f.a, { loc, full: fullLoc, phone: SITE.phone, storeListShort: (meta.stores || []).slice(0,3).join('·') })
    }))
  );

  const body = `${breadcrumbHtml([
    { name: '홈', url: '/' },
    { name: r.f, url: '/' + encodeKor(short) },
    { name: sigungu, url: '/' + encodeKor(short) + '/' + encodeKor(sigungu) },
    { name: dong, url: '/' + encodeKor(short) + '/' + encodeKor(sigungu) + '/' + encodeKor(dong) },
    { name: product.name }
  ])}
  <section class="hero"><div class="container"><div class="hero-grid">
    <div>
      <div class="hero-chip"><span class="hero-chip-dot"></span><span>${escapeHtml(fullLoc)} ${escapeHtml(product.name)}</span></div>
      <h1 style="white-space:pre-line">${escapeHtml(heroHeadline).replace('전문.','<span class="accent">전문.</span>').replace('해결.','<span class="accent">해결.</span>').replace('A/S까지.','<span class="accent">A/S까지.</span>').replace('솔루션.','<span class="accent">솔루션.</span>').replace('갑니다.','<span class="accent">갑니다.</span>')}</h1>
      <p class="hero-sub">${escapeHtml(heroSub)}</p>
      <div class="hero-ctas">
        <a class="btn btn-primary" href="tel:${SITE.phoneRaw}">${ICON.phone()} ${SITE.phone}</a>
        <a class="btn btn-outline" href="/제품/${encodeKor(product.slug)}">${escapeHtml(product.name)} 자세히 ${ICON.arrow()}</a>
      </div>
      ${trustChipsHtml(seed)}
    </div>
    <div class="hero-visual" style="display:flex;align-items:center;justify-content:center;background:var(--ivory);border-radius:var(--r-md);min-height:280px">
      <div style="text-align:center">${PRODUCT_ICON[product.iconKey](200)}<div style="margin-top:18px;font-size:14px;font-weight:700;color:var(--brown)">${escapeHtml(product.tagline)}</div></div>
    </div>
  </div></div></section>
  <section class="info"><div class="container">
    <div class="sec-label">${escapeHtml(product.name).toUpperCase()}</div>
    <h2>${escapeHtml(fullLoc)} ${escapeHtml(product.name)} 출장 설치 — ${escapeHtml(product.tagline)}</h2>
    <p>${escapeHtml(product.intro)}</p>
    <p>${escapeHtml(fitText)}</p>
    <h3>${escapeHtml(dong)} 매장 환경 분석</h3>
    <p>${escapeHtml(intro2)}</p>
    <p>${escapeHtml(fitText2)}</p>
    <h3>${escapeHtml(product.name)} 모델별 특징</h3>
    <ul>
      ${product.types.map(t => `<li><strong>${escapeHtml(t.name)}</strong> — ${escapeHtml(t.use)}</li>`).join('')}
    </ul>
    <h3>${escapeHtml(product.name)} 도입 효과</h3>
    <div class="bene-grid">
      ${product.benefits.map(b => `<div class="bene"><div class="bene-icon">${ICON.check()}</div><div class="bene-text">${escapeHtml(b)}</div></div>`).join('')}
    </div>
    <h3>${escapeHtml(dong)} 매장 운영 인사이트</h3>
    <p>${escapeHtml(insight)}</p>
    <h3>매장 규모별 추천 구성</h3>
    ${pickN(STORE_TYPE_RECS, seed, 3, 'rec').map(t => `<p>${escapeHtml(t)}</p>`).join('')}
    <h3>비용 안내</h3>
    ${pickN(COST_BLOCK, seed, 2, 'cost').map(t => `<p>${escapeHtml(fill(t, { loc: dong }))}</p>`).join('')}
    <h3>${escapeHtml(dong)} 인근 ${escapeHtml(product.name)} 설치 사례</h3>
    ${pickN(CASE_STUDIES, seed, 2, 'case').map(t => `<p>${escapeHtml(fill(t, { loc: dong }))}</p>`).join('')}
    <h3>설치 진행 순서</h3>
    <ol>
      ${product.process.map(s => `<li>${escapeHtml(s)}</li>`).join('')}
    </ol>
  </div></section>
  <section class="info sec-light"><div class="container">
    <div class="sec-label">FAQ</div>
    <h2>${escapeHtml(product.name)} 자주 묻는 질문</h2>
    <div class="faq">
      ${faqs.map(f => `<div class="faq-item"><div class="faq-q">${escapeHtml(f.q)}</div><div class="faq-a">${escapeHtml(f.a)}</div></div>`).join('')}
    </div>
  </div></section>
  ${ctaSectionHtml(loc, `${dong} 매장에 ${product.name} 설치하세요`)}`;
  return htmlDoc({
    title: `${fullLoc} ${product.name} 출장 설치 · ${SITE.name}`,
    desc: `${fullLoc} ${product.name} 출장 설치 전문. ${product.tagline}. 무료 견적 ${SITE.phone}.`,
    canonical: `${SITE.origin}/${encodeKor(short)}/${encodeKor(sigungu)}/${encodeKor(dong)}/${encodeKor(productSlug)}`,
    structuredData: { '@context':'https://schema.org','@type':'Product', name: `${fullLoc} ${product.name}`, description: product.intro, brand: SITE.name },
    body
  });
}

