// ─────────────────────── sitemap (분할) ───────────────────────
// 사이트맵 인덱스 + 분할 (Naver/Google 권장: 50,000 URL 미만 / 50MB 미만 per file)
function sitemapIndex() {
  const today = new Date().toISOString().split('T')[0];
  return `<?xml version="1.0" encoding="UTF-8"?>
<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
<sitemap><loc>${SITE.origin}/sitemap-main.xml</loc><lastmod>${today}</lastmod></sitemap>
<sitemap><loc>${SITE.origin}/sitemap-regions.xml</loc><lastmod>${today}</lastmod></sitemap>
<sitemap><loc>${SITE.origin}/sitemap-dongs.xml</loc><lastmod>${today}</lastmod></sitemap>
<sitemap><loc>${SITE.origin}/sitemap-products.xml</loc><lastmod>${today}</lastmod></sitemap>
</sitemapindex>`;
}
function buildSitemapXml(urls, today) {
  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls.map(u => `<url><loc>${escapeXml(u.loc)}</loc><lastmod>${today}</lastmod><changefreq>${u.f || 'weekly'}</changefreq><priority>${u.p || '0.5'}</priority></url>`).join('\n')}
</urlset>`;
}
function sitemapMain() {
  const today = new Date().toISOString().split('T')[0];
  const urls = [
    { loc: SITE.origin + '/', p: '1.0', f: 'weekly' },
    { loc: SITE.origin + '/지역', p: '0.9', f: 'weekly' },
    { loc: SITE.origin + '/소개', p: '0.5', f: 'monthly' }
  ];
  return buildSitemapXml(urls, today);
}
function sitemapRegions() {
  const today = new Date().toISOString().split('T')[0];
  const urls = [];
  for (const [short, r] of Object.entries(REGIONS_DATA)) {
    urls.push({ loc: SITE.origin + '/' + encodeKor(short), p: '0.8', f: 'weekly' });
    for (const sg of Object.keys(r.d)) {
      urls.push({ loc: SITE.origin + '/' + encodeKor(short) + '/' + encodeKor(sg), p: '0.7', f: 'weekly' });
    }
  }
  return buildSitemapXml(urls, today);
}
function sitemapDongs(part = 0, perPart = 5000) {
  const today = new Date().toISOString().split('T')[0];
  const urls = [];
  for (const [short, r] of Object.entries(REGIONS_DATA)) {
    for (const [sg, dongs] of Object.entries(r.d)) {
      for (const d of dongs) {
        urls.push({ loc: SITE.origin + '/' + encodeKor(short) + '/' + encodeKor(sg) + '/' + encodeKor(d), p: '0.6', f: 'monthly' });
      }
    }
  }
  // 동×제품 페이지도 포함 (조합)
  return buildSitemapXml(urls, today);
}
function sitemapProducts() {
  const today = new Date().toISOString().split('T')[0];
  const urls = [];
  for (const p of PRODUCTS) {
    urls.push({ loc: SITE.origin + '/제품/' + encodeKor(p.slug), p: '0.9', f: 'weekly' });
  }
  // 동×제품 조합도 여기에 (분리)
  for (const [short, r] of Object.entries(REGIONS_DATA)) {
    for (const [sg, dongs] of Object.entries(r.d)) {
      for (const d of dongs) {
        for (const p of PRODUCTS) {
          urls.push({ loc: SITE.origin + '/' + encodeKor(short) + '/' + encodeKor(sg) + '/' + encodeKor(d) + '/' + encodeKor(p.slug), p: '0.5', f: 'monthly' });
        }
      }
    }
  }
  return buildSitemapXml(urls, today);
}


// ============================================================
// 라우터 / fetch handler
// ============================================================

function htmlResp(html, status = 200) {
  return new Response(html, {
    status,
    headers: {
      'Content-Type': 'text/html; charset=utf-8',
      'Cache-Control': 'public, max-age=300, s-maxage=86400',
      'X-Frame-Options': 'SAMEORIGIN',
      'X-Content-Type-Options': 'nosniff',
      'Referrer-Policy': 'strict-origin-when-cross-origin'
    }
  });
}
function xmlResp(xml) {
  return new Response(xml, {
    status: 200,
    headers: {
      'Content-Type': 'application/xml; charset=utf-8',
      'Cache-Control': 'public, max-age=3600, s-maxage=86400'
    }
  });
}
function textResp(text) {
  return new Response(text, {
    status: 200,
    headers: {
      'Content-Type': 'text/plain; charset=utf-8',
      'Cache-Control': 'public, max-age=3600'
    }
  });
}

function notFoundResponse() {
  return new Response(notFoundPage(), {
    status: 404,
    headers: { 'Content-Type': 'text/html; charset=utf-8' }
  });
}

async function handle(request) {
  const url = new URL(request.url);
  let path = url.pathname;
  
  // 정규화
  if (path !== '/' && path.endsWith('/')) {
    return Response.redirect(url.origin + path.replace(/\/+$/,'') + url.search, 301);
  }
  
  // 시스템 라우트
  if (path === '/robots.txt') return textResp(robotsTxt());
  if (path === '/sitemap.xml') return xmlResp(sitemapIndex());
  if (path === '/sitemap-main.xml') return xmlResp(sitemapMain());
  if (path === '/sitemap-regions.xml') return xmlResp(sitemapRegions());
  if (path === '/sitemap-dongs.xml') return xmlResp(sitemapDongs());
  if (path === '/sitemap-products.xml') return xmlResp(sitemapProducts());
  if (path === '/favicon.ico') return new Response(null, { status: 204 });
  
  // 홈
  if (path === '/') return htmlResp(homePage());
  
  // 정적 페이지
  const decoded = decodeURIComponent(path);
  if (decoded === '/소개') return htmlResp(aboutPage());
  if (decoded === '/지역') return htmlResp(regionIndexPage());
  
  // 제품
  const productMatch = decoded.match(/^\/제품\/([^/]+)$/);
  if (productMatch) {
    const html = productPage(productMatch[1]);
    return html ? htmlResp(html) : notFoundResponse();
  }
  
  // 지역 라우트: /:region (/{short}/{sigungu}/{dong}/{product})
  const segments = decoded.split('/').filter(Boolean);
  
  if (segments.length === 1) {
    // 광역
    const html = regionPage(segments[0]);
    return html ? htmlResp(html) : notFoundResponse();
  }
  if (segments.length === 2) {
    // 시군구
    const html = districtPage(segments[0], segments[1]);
    return html ? htmlResp(html) : notFoundResponse();
  }
  if (segments.length === 3) {
    // 동읍면
    const html = dongPage(segments[0], segments[1], segments[2]);
    return html ? htmlResp(html) : notFoundResponse();
  }
  if (segments.length === 4) {
    // 동×제품
    const html = dongProductPage(segments[0], segments[1], segments[2], segments[3]);
    return html ? htmlResp(html) : notFoundResponse();
  }
  
  return notFoundResponse();
}

export default {
  async fetch(request, env, ctx) {
    try {
      return await handle(request);
    } catch (e) {
      return new Response('Server error: ' + e.message, { status: 500 });
    }
  }
};
